 /**
  * Hot spot handling for Pannellum
  */

+/**
+ * List of allowed HTML attributes for hot spot elements.
+ * Event handler attributes (on*) and other dangerous attributes are excluded.
+ * @type {Set<string>}
+ */
+const ALLOWED_HOTSPOT_ATTRIBUTES = new Set([
+    'class', 'id', 'style', 'title', 'role', 'tabindex',
+    'aria-label', 'aria-labelledby', 'aria-describedby', 'aria-hidden',
+    'aria-expanded', 'aria-controls', 'aria-live', 'aria-atomic'
+]);
+
+/**
+ * Checks if an attribute name is allowed for hot spot elements.
+ * Allows data-* and aria-* prefixed attributes.
+ * @param {string} attr - Attribute name to check
+ * @returns {boolean} True if attribute is allowed
+ */
+function isAllowedHotspotAttribute(attr) {
+    return ALLOWED_HOTSPOT_ATTRIBUTES.has(attr) ||
+           attr.startsWith('data-') ||
+           attr.startsWith('aria-');
+}
+
 /**
  * Creates a hot spot element from configuration
  * @param {Object} config - Hot spot configuration
  * @returns {HTMLElement} Hot spot element
@@ -45,11 +61,13 @@ export function createHotSpotElement(config) {
     // Apply custom attributes if provided
     if (config.attributes) {
         for (const [attr, value] of Object.entries(config.attributes)) {
-            element.setAttribute(attr, value);
+            if (isAllowedHotspotAttribute(attr)) {
+                element.setAttribute(attr, value);
+            } else {
+                console.warn(`Pannellum: Ignoring disallowed hot spot attribute "${attr}"`);
+            }
         }
     }

     return element;
 }

