   computed: {
+    parsedContent () {
+      if (!this.noHtml) {
+        return this.renderMarkdown(this.content)
+      }
+      
+      // When no-html is enabled, we need to sanitize headers specifically
+      const md = this.createMarkdownParser()
+      const tokens = md.parse(this.content, {})
+      return this.renderTokensWithSanitizedHeaders(tokens, md)
+    },
     markdownParser () {
       return new MarkdownIt({
         html: !this.noHtml,
         linkify: this.linkify,
         breaks: this.breaks,
         typographer: this.typographer
       })
@@ -65,6 +72,25 @@ export default {
       return parser
     },
     renderMarkdown (content) {
       return this.markdownParser.render(content)
     },
+    renderTokensWithSanitizedHeaders (tokens, md) {
+      // Walk tokens and escape header content when no-html is enabled
+      const sanitizedTokens = tokens.map(token => {
+        if (token.type === 'heading_open') {
+          // The next token should be the inline content of the header
+          return token
+        }
+        if (token.type === 'inline' && this.isHeaderContent(token)) {
+          // Escape HTML in header inline content
+          return {
+            ...token,
+            content: escapeHtml(token.content),
+            children: token.children?.map(child => ({
+              ...child,
+              content: child.type === 'text' ? escapeHtml(child.content) : child.content
+            }))
+          }
+        }
+        return token
+      })
+      return md.renderer.render(sanitizedTokens, md.options, {})
+    },
+    isHeaderContent (token) {
+      // Check if this inline token is inside a header
+      return token.hidden === false && token.tag === undefined && token.nesting === 0
+    }
   }
 }
 </script>

