+        'googleapis.com',
+        'google.com',
+        'identitytoolkit.googleapis.com',
+        'securetoken.googleapis.com'
+      ];
+      return trustedHosts.some(host => parsed.hostname === host || parsed.hostname.endsWith('.' + host));
+    } catch {
