@@ -0,0 +1,45 @@
+//! Policy enforcement for QE Identity.
+
+use crate::collateral::QeIdentity;
+use crate::error::{Error, Result};
+
+/// Policy constraints for QE Identity verification.
+#[derive(Debug, Clone)]
+pub struct QeIdentityPolicy {
+    /// Minimum required QE SVN (Security Version Number)
+    pub min_qe_svn: u16,
+    /// Allowed QE vendor IDs (Intel = 0x8086)
+    pub allowed_vendor_ids: Vec<u16>,
+    /// Allowed QE types (0 = SGX, 1 = TDX)
+    pub allowed_qe_types: Vec<u8>,
+}
+
+impl Default for QeIdentityPolicy {
+    fn default() -> Self {
+        Self {
+            min_qe_svn: 0, // Should be configured based on current TCB
+            allowed_vendor_ids: vec![0x8086], // Intel only
+            allowed_qe_types: vec![0, 1], // SGX and TDX
+        }
+    }
+}
+
+impl QeIdentityPolicy {
+    /// Enforces policy constraints on the QE Identity.
+    pub fn enforce(&self, qe_identity: &QeIdentity) -> Result<()> {
+        // Check vendor ID
+        if !self.allowed_vendor_ids.contains(&qe_identity.vendor_id) {
+            return Err(Error::PolicyViolation(format!(
+                "QE vendor ID 0x{:04x} not allowed",
+                qe_identity.vendor_id
+            )));
+        }
+
+        // Check QE type
+        if !self.allowed_qe_types.contains(&qe_identity.qe_type) {
+            return Err(Error::PolicyViolation(format!(
+                "QE type {} not allowed",
+                qe_identity.qe_type
+            )));
+        }
+
+        // Check QE SVN
+        if qe_identity.qe_svn < self.min_qe_svn {
+            return Err(Error::PolicyViolation(format!(
+                "QE SVN {} below minimum {}",
+                qe_identity.qe_svn, self.min_qe_svn
+            )));
+        }
+
+        Ok(())
+    }
+}
