@@ -0,0 +1,35 @@
+/**
+ * Safe function deserializer that prevents arbitrary code execution.
+ * Only allows deserialization of pre-registered, safe functions.
+ */
+
+// Registry of allowed functions (populated at build time)
+const allowedFunctions = new Map<string, Function>();
+
+/**
+ * Registers a function as safe for deserialization.
+ * Called automatically by the optimizer for server functions.
+ */
+export function registerSafeFunction(name: string, fn: Function): void {
+  allowedFunctions.set(name, fn);
+}
+
+/**
+ * Safely deserializes a function by name.
+ * Throws if the function is not in the allowed registry.
+ */
+export function safeDeserialize(serialized: string): Function {
+  // Expected format: "functionName" or "moduleName.functionName"
+  const func = allowedFunctions.get(serialized);
+  
+  if (!func) {
+    throw new Error(`Function "${serialized}" is not registered for safe deserialization.`);
+  }
+  
+  return func;
+}
+
+/**
+ * Clears the registry (for testing purposes only).
+ */
+export function __clearRegistry(): void {
+  allowedFunctions.clear();
+}
