@@ -0,0 +1,25 @@
+/**
+ * Validates Content-Type header to prevent code injection attacks.
+ * Only allows safe, well-known MIME types for file uploads.
+ */
+export function validateContentType(contentType: string): boolean {
+  // List of allowed MIME types for file uploads
+  const allowedMimeTypes = [
+    'image/jpeg',
+    'image/png',
+    'image/gif',
+    'image/webp',
+    'application/pdf',
+    'text/plain',
+    'application/msword',
+    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
+    'application/vnd.ms-excel',
+    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
+  ];
+
+  // Extract the MIME type without parameters (e.g., charset)
+  const mimeType = contentType.split(';')[0].trim().toLowerCase();
+
+  return allowedMimeTypes.includes(mimeType);
+}
